import{_ as s,l as r,o,c as l,v as a,p as n,x as i,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"Cookie 与会话","description":"","frontmatter":{"title":"Cookie 与会话","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cookies-sessions.md","filePath":"cs/cookies-sessions.md","lastUpdated":1789023840000}'),C={name:"cs/cookies-sessions.md"};function k(h,e,T,E,S,_){const t=r("Mermaid");return o(),l("div",null,[e[1]||(e[1]=a('<h1 id="cookie-与会话" tabindex="-1">Cookie 与会话 <a class="header-anchor" href="#cookie-与会话" aria-label="Permalink to &quot;Cookie 与会话&quot;">​</a></h1><div class="epigraph"><p>HTTP 无状态；Cookie 把小块状态交给用户代理回带，服务器才能认出「同一会话」。属性决定范围、寿命与是否只走 HTTPS。</p><footer>—— 据 RFC 6265 Cookies；RFC 9110 无状态对照整理</footer></div><p>主干 HTTP 已说无状态。<a href="/cs/http3">上一课</a> 不改语义。缺口是<strong>会话怎么挂上</strong>：Set-Cookie、作用域、Secure/HttpOnly/SameSite。本课不把内容协商写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>购物车、登录不能每请求重认证密码。Cookie：服务器 Set-Cookie，之后请求自动带 Cookie 头。域名与路径限制范围；Expires/Max-Age；Secure 限制 HTTPS；HttpOnly 挡脚本读；SameSite 减 CSRF。会话 ID 应是随机，服务器侧存会话——Cookie 里只放引用。持久连接复用时必须隔离不同用户，虚拟主机尤其。</p><p>不要把 Cookie 写成 JWT 课：可以是不透明 ID。</p><p><span class="marginnote">RFC 6265。第三方 Cookie 在浏览器政策下萎缩，本课钉协议对象。</span></p><h3 id="http-仍无状态" tabindex="-1">HTTP 仍无状态 <a class="header-anchor" href="#http-仍无状态" aria-label="Permalink to &quot;HTTP 仍无状态&quot;">​</a></h3><p>Cookie 外挂引用，服务器存会话。缓存必须 Vary。0-RTT 带 Cookie 有重放。IP 不能当身份。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：响应 Set-Cookie → 存储 → 后续请求带上。对照：服务端会话 vs 客户端存全部状态。与 QUIC 0-RTT：早数据带 Cookie 有重放，须绑定。</p>',11)),(o(),n(p,null,{default:i(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22Set-Cookie%22%5D%20--%3E%20UA%5B%22%E7%94%A8%E6%88%B7%E4%BB%A3%E7%90%86%E5%AD%98%E5%82%A8%22%5D%0A%20%20UA%20--%3E%20REQ%5B%22%E4%B9%8B%E5%90%8E%E8%AF%B7%E6%B1%82%E5%B8%A6%E5%9B%9E%22%5D%0A%20%20SID%5B%22%E4%B8%8D%E9%80%8F%E6%98%8E%E4%BC%9A%E8%AF%9D%20ID%22%5D%20--%3E%20SRV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E4%BC%9A%E8%AF%9D%E8%A1%A8%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CDN 缓存必须对 <code>Cookie</code> 与 <code>Set-Cookie</code> 正确 <code>Vary</code>，否则串会话——后课 CDN 层次。H2/H3 多请求共享连接，Cookie 仍按请求头。NAT 后 IP 不能当身份。TLS 入口提供机密，Cookie 提供关联。</p><p>安全：会话固定、CSRF、缺失 Secure 是边界，不写利用手册。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入浏览器存储 localStorage 的全部。内容协商与压缩是下一课。后课默认：会话 = Cookie 引用 + 服务器状态；HTTP 仍然无状态协议。</p><p>把整份用户档案放进 Cookie 会超大小且泄露。</p><p>上一课留下的缺口在本课收口；「Cookie 与会话」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/content-negotiation">内容协商与压缩</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Cookie 在无状态 HTTP 上外挂会话。</li><li>属性约束范围、寿命与信道。</li><li>缓存与 0-RTT 要防串会话与重放。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 6265；RFC 9110。</li></ul>',10))])}const u=s(C,[["render",k]]);export{m as __pageData,u as default};
